        for i, t in enumerate(seg):
            if t.rsplit("/", 1)[-1] != "git":
                continue   # prefix words (env, nohup, nice -n 5) are skipped, not trusted
            rest = seg[i + 1:]
            sub = next((x for x in rest if not x.startswith("-")), None)
            if sub != "commit":
                continue
            args = rest[rest.index("commit") + 1:]
            j = 0
            while j < len(args):
                a = args[j]
                if a == "--":
                    break
                if a in VALUE_OPTS:
                    j += 2   # never inspect a value: a message may mention --no-verify
                    continue
                if a == "--no-verify" or re.match(r"^-[a-zA-Z]*n[a-zA-Z]*$", a):
                    return f"git commit {a!r} skips the pre-commit gate"
